import pytest
from sqlalchemy import text

from app.db import engine


@pytest.mark.skipif(not engine.dialect.name.startswith("postgresql"), reason="PostgreSQL-specific")
def test_supabase_client_roles_have_only_rls_scoped_read_access():
    with engine.connect() as connection:
        # Exercise default privileges after the lockdown migration using objects created by postgres.
        connection.exec_driver_sql(
            "CREATE TABLE public.security_privilege_probe (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY)"
        )
        connection.exec_driver_sql("CREATE SEQUENCE public.security_privilege_probe_seq")
        roles = set(connection.execute(text(
            "SELECT rolname FROM pg_roles WHERE rolname IN ('anon', 'authenticated')"
        )).scalars())
        if not {"anon", "authenticated"}.issubset(roles):
            pytest.skip("Supabase client roles are not present")

        tables = connection.execute(text(
            "SELECT tablename FROM pg_tables WHERE schemaname = 'public'"
        )).scalars().all()
        readable = {
            "schemes", "nav_observations", "portfolios", "portfolio_transactions",
            "portfolio_transaction_audit", "portfolio_import_batches",
        }
        for table in tables:
            for privilege in ("SELECT", "INSERT", "UPDATE", "DELETE", "TRUNCATE", "REFERENCES", "TRIGGER"):
                allowed = connection.execute(
                    text("SELECT has_table_privilege(:role, :table_name, :privilege)"),
                    {"role": "anon", "table_name": f"public.{table}", "privilege": privilege},
                ).scalar_one()
                assert not allowed, f"anon unexpectedly has {privilege} on public.{table}"
                authenticated_allowed = connection.execute(
                    text("SELECT has_table_privilege('authenticated', :table_name, :privilege)"),
                    {"table_name": f"public.{table}", "privilege": privilege},
                ).scalar_one()
                expected = privilege == "SELECT" and table in readable
                assert authenticated_allowed == expected, (
                    f"authenticated privilege mismatch for {privilege} on public.{table}"
                )

        rls_tables = set(connection.execute(text(
            "SELECT relname FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace "
            "WHERE n.nspname = 'public' AND c.relkind = 'r' AND c.relrowsecurity"
        )).scalars())
        assert {
            "alembic_version", "schemes", "ingestion_snapshots", "portfolios",
            "nav_observations", "portfolio_transactions", "portfolio_transaction_audit",
            "nav_observation_revisions", "portfolio_import_batches",
            "fund_watchlist_items", "fund_research_snapshots",
            "benchmark_indices", "benchmark_observations",
            "benchmark_observation_revisions", "scheme_benchmark_assignments",
            "fund_holding_disclosures", "fund_holdings",
            "portfolio_goals", "portfolio_report_snapshots",
        }.issubset(rls_tables)

        sequences = connection.execute(text(
            "SELECT sequencename FROM pg_sequences WHERE schemaname = 'public'"
        )).scalars().all()
        for role in ("anon", "authenticated"):
            for sequence in sequences:
                for privilege in ("USAGE", "SELECT", "UPDATE"):
                    allowed = connection.execute(
                        text("SELECT has_sequence_privilege(:role, :sequence_name, :privilege)"),
                        {"role": role, "sequence_name": f"public.{sequence}", "privilege": privilege},
                    ).scalar_one()
                    assert not allowed, f"{role} unexpectedly has {privilege} on public.{sequence}"


@pytest.mark.skipif(not engine.dialect.name.startswith("postgresql"), reason="PostgreSQL-specific")
def test_financial_trigger_functions_pin_safe_search_path():
    with engine.connect() as connection:
        rows = connection.execute(text(
            "SELECT proname, proconfig FROM pg_proc p "
            "JOIN pg_namespace n ON n.oid = p.pronamespace "
            "WHERE n.nspname = 'public' "
            "AND proname IN ('prevent_financial_audit_mutation', 'protect_portfolio_transaction_mutation')"
        )).all()
    configs = {name: config or [] for name, config in rows}
    assert set(configs) == {
        "prevent_financial_audit_mutation",
        "protect_portfolio_transaction_mutation",
    }
    for config in configs.values():
        assert any(value.replace(" ", "") == "search_path=pg_catalog,public" for value in config)
    with engine.connect() as connection:
        installed = connection.execute(text(
            "SELECT 1 FROM pg_trigger WHERE tgrelid = 'public.portfolio_transactions'::regclass "
            "AND tgname = 'trg_portfolio_transactions_immutable' AND NOT tgisinternal"
        )).scalar_one_or_none()
    assert installed == 1


@pytest.mark.skipif(not engine.dialect.name.startswith("postgresql"), reason="PostgreSQL-specific")
def test_portfolio_rls_hides_other_users_rows():
    from uuid import uuid4
    from datetime import datetime, timezone

    user_a, user_b = str(uuid4()), str(uuid4())
    with engine.begin() as connection:
        portfolio_a = connection.execute(
            text(
                "INSERT INTO public.portfolios (owner_user_id, name, currency, created_at) "
                "VALUES (:owner, 'RLS User A', 'INR', :created_at) RETURNING id"
            ),
            {"owner": user_a, "created_at": datetime.now(timezone.utc)},
        ).scalar_one()
        connection.execute(
            text(
                "INSERT INTO public.portfolios (owner_user_id, name, currency, created_at) "
                "VALUES (:owner, 'RLS User B', 'INR', :created_at)"
            ),
            {"owner": user_b, "created_at": datetime.now(timezone.utc)},
        )
        connection.exec_driver_sql("SET LOCAL ROLE authenticated")
        connection.execute(
            text("SELECT set_config('request.jwt.claim.sub', :subject, true)"),
            {"subject": user_a},
        )
        visible = connection.execute(
            text("SELECT id FROM public.portfolios ORDER BY id")
        ).scalars().all()
        assert visible == [portfolio_a]



@pytest.mark.skipif(not engine.dialect.name.startswith("postgresql"), reason="PostgreSQL-specific")
def test_public_default_privileges_do_not_expose_future_objects_for_any_creator():
    with engine.connect() as connection:
        role_exists = connection.execute(text(
            "SELECT 1 FROM pg_roles WHERE rolname = 'supabase_admin'"
        )).scalar_one_or_none()
        if role_exists is None:
            pytest.skip("supabase_admin fixture is not present")

        grants = connection.execute(text(
            """
            WITH creators AS (
                SELECT oid, rolname
                  FROM pg_roles
                 WHERE has_schema_privilege(oid, 'public', 'CREATE')
            ),
            object_types AS (
                SELECT unnest(ARRAY['r'::"char", 'S'::"char", 'f'::"char"]) AS object_type
            ),
            effective_defaults AS (
                SELECT creators.rolname AS creator_role,
                       object_types.object_type,
                       array_cat(
                           COALESCE(global_acl.defaclacl, acldefault(object_types.object_type, creators.oid)),
                           COALESCE(schema_acl.defaclacl, '{}'::aclitem[])
                       ) AS effective_acl
                  FROM creators
                  CROSS JOIN object_types
                  LEFT JOIN pg_default_acl global_acl
                    ON global_acl.defaclrole = creators.oid
                   AND global_acl.defaclnamespace = 0
                   AND global_acl.defaclobjtype = object_types.object_type
                  LEFT JOIN pg_default_acl schema_acl
                    ON schema_acl.defaclrole = creators.oid
                   AND schema_acl.defaclnamespace = 'public'::regnamespace
                   AND schema_acl.defaclobjtype = object_types.object_type
            )
            SELECT effective_defaults.creator_role,
                   effective_defaults.object_type,
                   CASE WHEN acl.grantee = 0 THEN 'PUBLIC' ELSE grantee.rolname END AS grantee,
                   acl.privilege_type
              FROM effective_defaults
              CROSS JOIN LATERAL aclexplode(effective_defaults.effective_acl) acl
              LEFT JOIN pg_roles grantee ON grantee.oid = acl.grantee
             WHERE acl.grantee = 0 OR grantee.rolname IN ('anon', 'authenticated')
            """
        )).all()
    assert grants == [], f"Unsafe future-object grants remain for supabase_admin: {grants}"



@pytest.mark.skipif(not engine.dialect.name.startswith("postgresql"), reason="PostgreSQL-specific")
def test_global_function_default_lockdown_preserves_managed_schema_grants():
    with engine.connect() as connection:
        rows = connection.execute(text(
            """
            SELECT n.nspname, grantee.rolname, acl.privilege_type
              FROM pg_default_acl d
              JOIN pg_namespace n ON n.oid = d.defaclnamespace
              CROSS JOIN LATERAL aclexplode(d.defaclacl) acl
              JOIN pg_roles grantee ON grantee.oid = acl.grantee
             WHERE d.defaclrole = 'supabase_admin'::regrole
               AND d.defaclobjtype = 'f'
               AND n.nspname IN ('extensions', 'graphql_public')
               AND grantee.rolname IN ('anon', 'authenticated')
               AND acl.privilege_type = 'EXECUTE'
            """
        )).all()
    assert {
        ("extensions", "anon", "EXECUTE"),
        ("extensions", "authenticated", "EXECUTE"),
        ("graphql_public", "anon", "EXECUTE"),
        ("graphql_public", "authenticated", "EXECUTE"),
    }.issubset(set(rows))



@pytest.mark.skipif(not engine.dialect.name.startswith("postgresql"), reason="PostgreSQL-specific")
def test_rls_isolates_portfolios_transactions_audit_and_imports_between_users():
    from datetime import date, datetime, timezone
    from hashlib import sha256
    from uuid import uuid4

    user_a, user_b = str(uuid4()), str(uuid4())
    scheme_code = 900_000_000 + (uuid4().int % 90_000_000)
    now = datetime.now(timezone.utc)

    with engine.connect() as connection:
        transaction = connection.begin()
        try:
            connection.execute(
                text(
                    "INSERT INTO public.schemes "
                    "(scheme_code, scheme_name, first_seen_at, last_seen_at) "
                    "VALUES (:code, 'RLS isolation test scheme', :first_seen, :last_seen)"
                ),
                {"code": scheme_code, "first_seen": now, "last_seen": now},
            )
            portfolio_a = connection.execute(
                text(
                    "INSERT INTO public.portfolios (owner_user_id, name, currency, created_at) "
                    "VALUES (:owner, 'RLS A', 'INR', :created_at) RETURNING id"
                ),
                {"owner": user_a, "created_at": now},
            ).scalar_one()
            portfolio_b = connection.execute(
                text(
                    "INSERT INTO public.portfolios (owner_user_id, name, currency, created_at) "
                    "VALUES (:owner, 'RLS B', 'INR', :created_at) RETURNING id"
                ),
                {"owner": user_b, "created_at": now},
            ).scalar_one()

            transaction_ids = {}
            import_ids = {}
            for owner, portfolio_id in (("a", portfolio_a), ("b", portfolio_b)):
                transaction_ids[owner] = connection.execute(
                    text(
                        """
                        INSERT INTO public.portfolio_transactions
                            (portfolio_id, scheme_code, transaction_type, transaction_date,
                             units, nav, amount, charges, created_at)
                        VALUES
                            (:portfolio_id, :scheme_code, 'BUY', :transaction_date,
                             1, 100, 100, 0, :created_at)
                        RETURNING id
                        """
                    ),
                    {
                        "portfolio_id": portfolio_id,
                        "scheme_code": scheme_code,
                        "transaction_date": date(2026, 1, 1),
                        "created_at": now,
                    },
                ).scalar_one()
                connection.execute(
                    text(
                        """
                        INSERT INTO public.portfolio_transaction_audit
                            (transaction_id, event_type, event_at, details_json)
                        VALUES (:transaction_id, 'CREATED', :event_at, '{}')
                        """
                    ),
                    {"transaction_id": transaction_ids[owner], "event_at": now},
                )
                import_ids[owner] = connection.execute(
                    text(
                        """
                        INSERT INTO public.portfolio_import_batches
                            (portfolio_id, statement_sha256, imported_at, imported_count)
                        VALUES (:portfolio_id, :fingerprint, :imported_at, 1)
                        RETURNING id
                        """
                    ),
                    {
                        "portfolio_id": portfolio_id,
                        "fingerprint": sha256(uuid4().bytes).hexdigest(),
                        "imported_at": now,
                    },
                ).scalar_one()

            connection.exec_driver_sql("SET LOCAL ROLE authenticated")
            for owner, subject in (("a", user_a), ("b", user_b)):
                connection.execute(
                    text("SELECT set_config('request.jwt.claim.sub', :subject, true)"),
                    {"subject": subject},
                )
                expected_portfolio = portfolio_a if owner == "a" else portfolio_b
                assert connection.execute(
                    text("SELECT id FROM public.portfolios ORDER BY id")
                ).scalars().all() == [expected_portfolio]
                assert connection.execute(
                    text("SELECT id FROM public.portfolio_transactions ORDER BY id")
                ).scalars().all() == [transaction_ids[owner]]
                assert connection.execute(
                    text("SELECT transaction_id FROM public.portfolio_transaction_audit ORDER BY id")
                ).scalars().all() == [transaction_ids[owner]]
                assert connection.execute(
                    text("SELECT id FROM public.portfolio_import_batches ORDER BY id")
                ).scalars().all() == [import_ids[owner]]
        finally:
            transaction.rollback()
